'use strict';
const fs=require('fs'),path=require('path'),crypto=require('crypto'),sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const root=path.resolve(__dirname,'..'),r=JSON.parse(fs.readFileSync(path.join(root,'independent-engine/pilot-results.json'))),{zipEntries}=require('../../tools/inspect-android-archive.cjs'),{inspectClass}=require('../independent-engine/classfile-coverage.cjs');
for(const x of r.commands)if(sha(fs.readFileSync(x.log))!==x.logSha256||x.timedOut||x.signal||x.error||x.exitCode!==0||x.elapsedMs>x.timeoutMs)throw Error('Command evidence mismatch');
const jars=new Map();for(const x of r.conversions){const b=fs.readFileSync(x.output);if(sha(b)!==x.sha256||b.length!==x.bytes)throw Error('JAR mismatch');jars.set(x.input.dexEntry,zipEntries(b));}
let classes=0,methods=0,java=0,markers=0;
for(const cov of r.coverage){for(const x of cov.closure){const entries=jars.get(x.dexEntry).filter(e=>e.name===x.classEntry);if(entries.length!==1)throw Error('Closure entry');const info=inspectClass(entries[0].read());if(info.sha256!==x.classSha256||info.descriptor!==x.descriptor||info.methods.some(m=>m.codePresenceIssues.length)||JSON.stringify(info.methods.map(m=>m.signature))!==JSON.stringify(x.methods.map(m=>m.signature)))throw Error('Class evidence');classes++;}const owner=cov.closure.find(x=>x.descriptor===cov.descriptor);if(JSON.stringify(owner.methods.map(x=>x.signature).sort())!==JSON.stringify([...cov.expectedRootMethods].sort()))throw Error('Exact method set');methods+=owner.methods.length;}
for(const d of r.decompilations)for(const x of d.files){const b=fs.readFileSync(x.file);if(sha(b)!==x.sha256||b.length!==x.bytes)throw Error('Output mismatch');if(!x.path.endsWith('.java'))continue;java++;const lines=b.toString().split(/\r?\n/);for(const line of lines){const comment=/^\s*(\/\*|\*|\/\/)/.test(line),diagnostic=/Could not decompile|Decompilation failed|Exception decompiling|Unable to|WARNING|ERROR/i.test(line),failureThrow=/throw new [A-Za-z0-9_.]+\("(?:Decompilation failed|Could not decompile)/.test(line);if((comment&&diagnostic)||failureThrow)markers++;}}
if(classes!==20||methods!==98||java!==3||markers!==8||r.status!=='PARTIAL-CANDIDATES-UNREVIEWED')throw Error('Summary mismatch');
const out={status:'PASS',score:10,scope:'Execution/integrity only; no semantic promotion',resultsSha256:sha(fs.readFileSync(path.join(root,'independent-engine/pilot-results.json'))),verifiedClosureClasses:classes,verifiedExactRootDescriptors:methods,javaFiles:java,cfrDiagnosticMarkerLines:markers,checks:['All four command log hashes, exits and wall limits','Both converted JAR hashes/sizes','All twenty closure class identities/hashes and Code-presence checks','Exact ninety-eight root descriptor set','All emitted output hashes and diagnostic comment/failure-throw lines recounted'],limits:['a.b source absent despite classfile presence','K6 has two CFR failure stubs within eight diagnostic lines','Ordinary identifiers containing Warning/Error are excluded from diagnostic counts','Clean Material output is not semantic validation'],commitApproved:false};
fs.writeFileSync(path.join(__dirname,'INDEPENDENT-ENGINE-RESULTS.json'),JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify(out));
